    songs = pl.get('songs', [])
    song_ids = [s['id'] for s in songs]
    if all(sid in downloaded_song_durations for sid in song_ids):
        total_duration = sum(downloaded_song_durations[sid] for sid in song_ids)
        print(f"Playlist {pid} ({pl['title']}): all downloaded, total duration {total_duration}s")
        if total_duration >= 1800:
            print(f"Selected playlist {pid} with duration {total_duration}s")
            break
    else:
        print(f"Playlist {pid} ({pl['title']}): not all downloaded")

